def f(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    out=[[bg]*w for _ in range(h)]
    cells=[(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j] not in (bg,2)]
    shape_rows={i for i,_,_ in cells}
    drow=max(shape_rows)+1
    while max(shape_rows)<drow-1:
        bot=max(i for i,_,_ in cells)
        cells=[(i+1,j,x) for (i,j,x) in cells if i!=bot]
        shape_rows={i for i,_,_ in cells}
    tr=min(i for i,_,_ in cells)-1
    out[tr]=[8]*w
    for (i,j,x) in cells: out[i][j]=x
    return out
